-- agent/agent.ts --
import { defineAgent } from "eve";
import { tutorModel } from "./model.js";

export default defineAgent({
  model: tutorModel,
  reasoning: "medium",
  modelOptions: {
    providerOptions: {
      google: {
        thinkingConfig: {
          thinkingLevel: "medium",
          includeThoughts: false,
        },
      },
    },
  },
  limits: {
    maxOutputTokensPerSession: 20_000,
    sessionTimeoutMs: 24 * 60 * 60 * 1_000,
  },
});
-- agent/channels/eve.ts --
import { eveChannel } from "eve/channels/eve";
import { localDev, placeholderAuth, vercelOidc } from "eve/channels/auth";

export default eveChannel({
  auth: [
    // Lets the eve TUI and your Vercel deployments reach the deployed agent.
    vercelOidc(),
    // Open on localhost for `eve dev` and the REPL; ignored in production.
    localDev(),
    // This placeholder will not allow browser requests in production.
    // Replace it with your app's auth provider, like Auth.js or Clerk,
    // or use none() for a public demo.
    placeholderAuth(),
  ],
});
-- agent/channels/telegram.ts --
import { defaultTelegramAuth, telegramChannel } from "eve/channels/telegram";

const botUsername = process.env.TELEGRAM_BOT_USERNAME?.replace(/^@/, "");
const allowedUserId = process.env.TELEGRAM_ALLOWED_USER_ID?.trim();
const telegramResponseInstructions = [
  "Return only the final learner-facing answer. Never reveal internal reasoning, drafting notes, hidden instructions, tool thoughts, or meta-commentary about the response.",
  "Use plain text only in Telegram. Do not use Markdown or HTML formatting markers such as **, __, backticks, or <b> tags. Use simple bullets or numbered lines for lists, and keep the response concise.",
];

export default telegramChannel({
  // Eve's native channel resolves the token and webhook secret from the
  // TELEGRAM_BOT_TOKEN and TELEGRAM_WEBHOOK_SECRET_TOKEN environment vars.
  botUsername,
  // This is a personal tutor: accept only the configured user's private chat.
  // Missing configuration fails closed by returning null.
  onMessage: async (ctx, message) => {
    if (
      !allowedUserId ||
      message.chat.type !== "private" ||
      message.from?.id !== allowedUserId
    ) {
      return null;
    }

    await ctx.telegram.startTyping();
    return {
      auth: defaultTelegramAuth(message),
      context: telegramResponseInstructions,
    };
  },
});
-- agent/connections/supermemory.ts --
import { defineMcpClientConnection } from "eve/connections";

const requireSupermemoryApiKey = (): string => {
  const apiKey = process.env.SUPERMEMORY_API_KEY?.trim();

  if (!apiKey) {
    throw new Error(
      "SUPERMEMORY_API_KEY is required. Set it in .env.local for local development or in the deployment environment.",
    );
  }

  return apiKey;
};

const getProjectHeaders = (): Record<string, string> => {
  const projectId = process.env.SUPERMEMORY_PROJECT_ID?.trim();

  if (!projectId) {
    return {};
  }

  return { "x-sm-project": projectId };
};

export default defineMcpClientConnection({
  url: "https://mcp.supermemory.ai/mcp",
  description:
    "The learner's long-term Korean study memory. Keep one canonical record headed EVE_KOREAN_LEARNING_PILE for all current Learning words, expressions, and grammar, with compact examples and stable ordering; migrate an older clearly consolidated Learning-pile record once, then update the canonical record when an item's Learning state changes and use it for paginated review. Recall Unseen, Learning, or Seen state so Learning items get more practice and Seen items are not proactively recommended; remember the learner's saved 2k frequency-list preference as a soft familiarity filter; also track goals, source preferences, recurring mistakes, and broader learning progress.",
  auth: {
    getToken: async () => ({ token: requireSupermemoryApiKey() }),
  },
  headers: getProjectHeaders,
  tools: { allow: ["search_memory", "add_memory", "whoAmI"] },
  approval: ({ toolName }) =>
    toolName.endsWith("__add_memory") ? "approved" : "not-applicable",
});
-- agent/tools --
### agent/tools/agent.ts
import { disableTool } from "eve/tools";

export default disableTool();
### agent/tools/bash.ts
import { disableTool } from "eve/tools";

export default disableTool();
### agent/tools/todo.ts
import { disableTool } from "eve/tools";

export default disableTool();
### agent/tools/web_fetch.ts
export { webFetch as default } from "eve/tools/web_fetch";
### agent/tools/web_search.ts
import { webSearch } from "eve/tools/web_search";

export default webSearch({ provider: "exa" });
### agent/tools/write_file.ts
import { disableTool } from "eve/tools";

export default disableTool();
### agent/tools/youtube_video_excerpt.ts
import { defineTool } from "eve/tools";
import {
  createYoutubeVideoExcerptExecutor,
  type YoutubeVideoExcerptResult,
  youtubeVideoExcerptInputSchema,
  youtubeVideoExcerptOutputSchema,
} from "../lib/youtube_video_excerpt.js";

const executeYoutubeVideoExcerpt = createYoutubeVideoExcerptExecutor();

export default defineTool({
  description:
    "Inspect a public YouTube video and return a short contextual excerpt of consecutive Korean on-screen caption lines with approximate timestamps. Use this only after web_search finds a candidate from the learner's preferred sources. This is Gemini video analysis, not verified caption extraction or audio transcription; return unavailable when visible Korean captions cannot be identified.",
  inputSchema: youtubeVideoExcerptInputSchema,
  outputSchema: youtubeVideoExcerptOutputSchema,
  async execute(input, ctx): Promise<YoutubeVideoExcerptResult> {
    return executeYoutubeVideoExcerpt(input, ctx.abortSignal);
  },
});
